import React, { useState, useEffect, useRef } from "react";

function RecipeGenerator() {
  const [darkMode, setDarkMode] = useState(false);
  const [mode, setMode] = useState("ingredients"); // "ingredients" or "name"
  const [recipeName, setRecipeName] = useState("");
  const [ingredients, setIngredients] = useState("");
  const [mealType, setMealType] = useState("Breakfast");
  const [cuisine, setCuisine] = useState("");
  const [cookingTime, setCookingTime] = useState("Less than 30 minutes");
  const [complexity, setComplexity] = useState("Beginner");
  const [recipes, setRecipes] = useState([]);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  const leftContentRef = useRef(null);
  const rightContentRef = useRef(null);

  const matchHeights = () => {
    if (leftContentRef.current && rightContentRef.current) {
      const leftHeight = leftContentRef.current.offsetHeight;
      rightContentRef.current.style.height = `${leftHeight}px`;
      console.log("Left content height:", leftHeight, "Right content height set to:", rightContentRef.current.offsetHeight);
    }
  };

  useEffect(() => {
    // Match heights after initial render and on state changes
    const handleResize = () => setTimeout(matchHeights, 100); // Delay to ensure DOM update
    handleResize(); // Run with delay
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, [mode, ingredients, mealType, cuisine, cookingTime, complexity, recipeName]);

  const handleSubmitByName = async () => {
    if (!recipeName) {
      setError("Please enter a recipe name.");
      return;
    }
    setLoading(true);
    try {
      const response = await fetch("http://localhost:5000/api/generate-by-name", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ recipeName }),
      });
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      console.log("Fetch Response Data:", data);
      if (data.error) {
        throw new Error(data.error);
      }
      if (data.recipe) {
        const normalizedRecipes = Array.isArray(data.recipe) ? data.recipe : [data.recipe];
        console.log("Normalized Recipes:", normalizedRecipes);
        setRecipes(normalizedRecipes);
        setError(null);
      } else {
        setRecipes([]);
      }
    } catch (err) {
      console.error("Error generating recipe by name:", err);
      setError(`Failed to generate recipe by name: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmitByIngredients = async () => {
    setLoading(true);
    try {
      const response = await fetch("http://localhost:5000/api/generate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ingredients,
          mealType,
          cuisine,
          cookingTime,
          complexity,
        }),
      });
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      console.log("API Response by Ingredients:", data);
      if (data.error) {
        throw new Error(data.error);
      }
      if (data.recipe) {
        const normalizedRecipes = Array.isArray(data.recipe) ? data.recipe : [data.recipe];
        setRecipes(normalizedRecipes);
      } else {
        setRecipes([]);
      }
    } catch (err) {
      console.error("Error generating recipe:", err);
      setError(`Failed to generate recipe: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = () => {
    if (mode === "name") {
      handleSubmitByName();
    } else {
      handleSubmitByIngredients();
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-white to-gray-100 dark:from-gray-900 dark:to-gray-800 flex items-center justify-center p-4 transition-colors duration-300">
      <div className="absolute top-4 right-4 flex space-x-2">
        <button
          onClick={() => setDarkMode(!darkMode)}
          className="bg-gray-800 dark:bg-white text-white dark:text-black px-4 py-2 rounded shadow hover:opacity-80"
        >
          {darkMode ? "☀️" : "🌙"}
        </button>
        <button
          onClick={() => setTimeout(matchHeights, 100)}
          className="bg-gray-800 dark:bg-white text-white dark:text-black px-4 py-2 rounded shadow hover:opacity-80"
        >
          Sync Heights
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 w-full max-w-6xl h-full">
        {/* MIDDLE - Recipe Generator Panel */}
        <div className="bg-white dark:bg-gray-700 dark:text-white rounded-xl shadow-md border-2 border-green-500 panel">
          <div className="p-6">
            <h2 className="text-xl font-bold text-center mb-6">Recipe Generator</h2>

            {/* Mode Switch */}
            <div className="mb-6 flex justify-center">
              <label className="flex items-center space-x-2 cursor-pointer">
                <span className="text-gray-800 dark:text-white">By Ingredients</span>
                <input
                  type="checkbox"
                  checked={mode === "name"}
                  onChange={() => setMode(mode === "ingredients" ? "name" : "ingredients")}
                  className="toggle-checkbox"
                />
                <span className="toggle-switch"></span>
                <span className="text-gray-800 dark:text-white">By Name</span>
              </label>
              <style>
                {`
                  .toggle-checkbox {
                    display: none;
                  }
                  .toggle-switch {
                    width: 40px;
                    height: 20px;
                    background-color: #ccc;
                    border-radius: 10px;
                    position: relative;
                    cursor: pointer;
                    transition: background-color 0.3s;
                  }
                  .toggle-checkbox:checked + .toggle-switch {
                    background-color: #4b9af4;
                  }
                  .toggle-switch::after {
                    content: '';
                    width: 16px;
                    height: 16px;
                    background-color: white;
                    border-radius: 50%;
                    position: absolute;
                    top: 2px;
                    left: 2px;
                    transition: transform 0.3s;
                  }
                  .toggle-checkbox:checked + .toggle-switch::after {
                    transform: translateX(20px);
                  }
                `}
              </style>
            </div>

            {/* Conditional Fields */}
            <div ref={leftContentRef} className="flex-grow">
              {mode === "ingredients" ? (
                <>
                  <div className="mb-4">
                    <label className="block font-semibold mb-1" htmlFor="ingredients">
                      Ingredients
                    </label>
                    <input
                      id="ingredients"
                      type="text"
                      className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
                      placeholder="e.g. tomato, potato, onion"
                      value={ingredients}
                      onChange={(e) => setIngredients(e.target.value)}
                    />
                  </div>

                  <div className="mb-4">
                    <label className="block font-semibold mb-1">Meal Type</label>
                    <select
                      className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
                      value={mealType}
                      onChange={(e) => setMealType(e.target.value)}
                    >
                      <option>Breakfast</option>
                      <option>Lunch</option>
                      <option>Dinner</option>
                      <option>Snack</option>
                    </select>
                  </div>

                  <div className="mb-4">
                    <label className="block font-semibold mb-1">Cuisine Preference</label>
                    <input
                      type="text"
                      className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
                      placeholder="e.g. Indian, Italian"
                      value={cuisine}
                      onChange={(e) => setCuisine(e.target.value)}
                    />
                  </div>

                  <div className="mb-4">
                    <label className="block font-semibold mb-1">Cooking Time</label>
                    <select
                      className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
                      value={cookingTime}
                      onChange={(e) => setCookingTime(e.target.value)}
                    >
                      <option>Less than 30 minutes</option>
                      <option>30-60 minutes</option>
                      <option>More than 1 hour</option>
                    </select>
                  </div>

                  <div className="mb-6">
                    <label className="block font-semibold mb-1">Complexity</label>
                    <select
                      className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
                      value={complexity}
                      onChange={(e) => setComplexity(e.target.value)}
                    >
                      <option>Beginner</option>
                      <option>Intermediate</option>
                      <option>Advanced</option>
                    </select>
                  </div>
                </>
              ) : (
                <div className="mb-4">
                  <label className="block font-semibold mb-1" htmlFor="recipeName">
                    Recipe Name
                  </label>
                  <input
                    id="recipeName"
                    type="text"
                    className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
                    placeholder="e.g. pizza"
                    value={recipeName}
                    onChange={(e) => setRecipeName(e.target.value)}
                  />
                </div>
              )}
            </div>

            <button
              onClick={handleSubmit}
              className="bg-blue-500 hover:bg-blue-600 text-white font-bold py-2 px-4 rounded w-full mt-auto"
            >
              Generate Recipe
            </button>
          </div>
        </div>

        {/* RIGHT - Recipe Output */}
        <div className="bg-white dark:bg-gray-700 rounded-xl shadow-md border-2 border-red-500 panel">
          <div className="p-6">
            <h2 className="text-xl font-bold mb-4 text-center text-gray-800 dark:text-white">
              Recipe Details
            </h2>

            <div ref={rightContentRef} className="flex-grow">
              {error && (
                <p className="text-red-500 dark:text-red-400 text-center mb-4">
                  {error}
                </p>
              )}
              {loading && (
                <div className="flex items-center justify-center h-full">
                  <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-blue-500"></div>
                </div>
              )}
              {recipes.length === 0 && !loading && (
                <p className="text-gray-500 dark:text-gray-300 text-center h-full flex items-center justify-center">
                  No recipe yet. Use the panels to generate a recipe.
                </p>
              )}
              {recipes.length > 0 && !loading && (
                <div className="space-y-6">
                  {recipes.map((recipe, index) => (
                    <div
                      key={index}
                      className="rounded-xl bg-white dark:bg-gray-800 shadow-md p-4 border dark:border-gray-700 transition-all duration-300 max-h-96 overflow-y-auto scrollbar-thin scrollbar-thumb-gray-400 scrollbar-track-gray-200 dark:scrollbar-thumb-gray-600 dark:scrollbar-track-gray-700"
                    >
                      {typeof recipe === "string" ? (
                        <div className="text-sm space-y-2 text-gray-800 dark:text-white">
                          {(() => {
                            const sections = {
                              title: "",
                              ingredients: [],
                              equipment: [],
                              instructions: [],
                              tips: [],
                            };
                            let currentSection = null;

                            const lines = recipe.split("\n").map((line) => line.trim().replace(/\r$/, ""));

                            lines.forEach((line) => {
                              if (/^\*\*(.*?)\*\*$/.test(line)) {
                                const headerText = line.replace(/\*\*/g, "").trim();
                                if (headerText.toLowerCase().includes("recipe title")) currentSection = "title";
                                else if (headerText.toLowerCase().includes("ingredients")) currentSection = "ingredients";
                                else if (headerText.toLowerCase().includes("equipment")) currentSection = "equipment";
                                else if (headerText.toLowerCase().includes("instructions")) currentSection = "instructions";
                                else if (headerText.toLowerCase().includes("optional tips") || headerText.toLowerCase().includes("serving or variations"))
                                  currentSection = "tips";
                                else currentSection = null;
                              } else if (line && currentSection) {
                                if (currentSection === "title") sections.title = line;
                                else if ((currentSection === "ingredients" || currentSection === "equipment" || currentSection === "tips") && /^[-•]/.test(line))
                                  sections[currentSection].push(line.replace(/^[-•]\s*/, ""));
                                else if (currentSection === "instructions" && !/^\*\*(.*?)\*\*$/.test(line))
                                  sections.instructions.push(line);
                              }
                            });

                            return (
                              <>
                                {sections.title && (
                                  <h3 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-4">{sections.title}</h3>
                                )}
                                {sections.ingredients.length > 0 && (
                                  <div>
                                    <h4 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-2">Ingredients</h4>
                                    <ul className="list-disc list-inside space-y-1 text-gray-800 dark:text-gray-200 text-sm">
                                      {sections.ingredients.map((ing, i) => (
                                        <li key={i}>{ing}</li>
                                      ))}
                                    </ul>
                                  </div>
                                )}
                                {sections.equipment.length > 0 && (
                                  <div>
                                    <h4 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-2 mt-4">Equipment</h4>
                                    <ul className="list-disc list-inside space-y-1 text-gray-800 dark:text-gray-200 text-sm">
                                      {sections.equipment.map((eq, i) => (
                                        <li key={i}>{eq}</li>
                                      ))}
                                    </ul>
                                  </div>
                                )}
                                {sections.instructions.length > 0 && (
                                  <div>
                                    <h4 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-2 mt-4">Instructions</h4>
                                    <div className="text-sm text-gray-800 dark:text-gray-200 whitespace-pre-wrap leading-relaxed">
                                      {sections.instructions.map((step, i) => (
                                        <p key={i}>{step}</p>
                                      ))}
                                    </div>
                                  </div>
                                )}
                                {sections.tips.length > 0 && (
                                  <div>
                                    <h4 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-2 mt-4">Optional Tips & Variations</h4>
                                    <ul className="list-disc list-inside space-y-1 text-gray-800 dark:text-gray-200 text-sm">
                                      {sections.tips.map((tip, i) => (
                                        <li key={i}>{tip}</li>
                                      ))}
                                    </ul>
                                  </div>
                                )}
                              </>
                            );
                          })()}
                        </div>
                      ) : (
                        <>
                          {recipe.title && (
                            <h3 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-4">{recipe.title}</h3>
                          )}
                          {recipe.ingredients && (
                            <div>
                              <h4 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-2">Ingredients</h4>
                              <ul className="list-disc list-inside space-y-1 text-gray-800 dark:text-gray-200 text-sm">
                                {recipe.ingredients.map((ing, i) => (
                                  <li key={i}>{ing}</li>
                                ))}
                              </ul>
                            </div>
                          )}
                          {recipe.equipment && (
                            <div>
                              <h4 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-2 mt-4">Equipment</h4>
                              <ul className="list-disc list-inside space-y-1 text-gray-800 dark:text-gray-200 text-sm">
                                {recipe.equipment.map((eq, i) => (
                                  <li key={i}>{eq}</li>
                                ))}
                              </ul>
                            </div>
                          )}
                          {recipe.instructions && (
                            <div>
                              <h4 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-2 mt-4">Instructions</h4>
                              <div className="text-sm text-gray-800 dark:text-gray-200 whitespace-pre-wrap leading-relaxed">
                                {recipe.instructions}
                              </div>
                            </div>
                          )}
                          {recipe.tips && (
                            <div>
                              <h4 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-2 mt-4">Optional Tips & Variations</h4>
                              <div className="text-sm text-gray-800 dark:text-gray-200 whitespace-pre-wrap leading-relaxed">
                                {recipe.tips}
                              </div>
                            </div>
                          )}
                        </>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
      <style>
        {`
          .panel {
            box-sizing: border-box;
            min-height: 0;
            height: auto; /* Allow natural height based on content */
          }
          .panel > .p-6 {
            flex-grow: 1;
            display: flex;
            flex-direction: column;
          }
          .panel .flex-grow {
            flex-grow: 1;
            display: flex;
            flex-direction: column;
            height: 100%;
          }
        `}
      </style>
    </div>
  );
}

export default RecipeGenerator;
